#!/usr/bin/env python3
"""Battle Zone V6.1 gameplay, controls, lobby and world-detail patch."""
from pathlib import Path
import sys
root=Path(sys.argv[1] if len(sys.argv)>1 else '.').resolve()
www=root/'app/src/main/assets/www'
html_path=www/'index.html'; model_path=www/'js/models.js'
if not html_path.is_file() or not model_path.is_file(): raise SystemExit('game HTML or rigged model loader missing')
html=html_path.read_text(encoding='utf-8'); models=model_path.read_text(encoding='utf-8')
marker='BATTLEZONE_V6_GAMEPLAY_OVERHAUL_V1'
if marker in html:
 print(marker,'already applied');raise SystemExit(0)
def one(src,old,new,label):
 n=src.count(old)
 if n!=1:raise SystemExit(f'{label}: expected one anchor, found {n}')
 return src.replace(old,new,1)

# The default player owns two actual weapon slots before touching ground loot.
html=one(html,"P.w=0;P.own=W.map((_,i)=>+(i==0));P.mags=[30];", "P.w=0;P.own=W.map((_,i)=>+(i<2));P.mags=W.map((w,i)=>i<2?w.m:0);",'two-weapon deployment loadout')
html=one(html,"function gunUpd(){while(gun.children.length)gun.remove(gun.children[0]);const g=mkGun(W[P.w].n);g.rotation.y=Math.PI;g.scale.setScalar(.62);gun.add(g);if(window.pmS&&window.pmS.setGun)window.pmS.setGun(W[P.w].n)}", "function gunUpd(){while(gun.children.length)gun.remove(gun.children[0]);const g=mkGun(W[P.w].n);g.rotation.y=Math.PI;g.scale.setScalar(.62);gun.add(g);window.BZActiveWeapon=W[P.w].n;if(window.pmS&&window.pmS.setGun)window.pmS.setGun(W[P.w].n);if(window.pmS&&window.BZModels?.setWeapon)window.BZModels.setWeapon(window.pmS.root,W[P.w].n)}",'live weapon synchronization')
html=one(html,"function jump(){if(P.air==2){P.air=1;P.y=Math.min(P.y-1,PLANE.y-3);", "function jump(){if(P.air==2){P.air=1;key.sprint=false;const sb=$('sprint');if(sb)sb.classList.remove('on');P.tp=true;gun.visible=false;window.BZActiveWeapon=W[P.w].n;if(pm&&pm.setGun)pm.setGun(W[P.w].n);P.y=Math.min(P.y-1,PLANE.y-3);",'aircraft weapon transition')
# Replace the old sprint toggle with a cancellation-safe hold control.
html=one(html,"bind('rel',reload);bind('sprint',()=>key.sprint=!key.sprint);bind('pjump',jump);", "bind('rel',reload);bind('pjump',jump);",'remove broken sprint toggle')
anchor="bind('fire',()=>fire=true,()=>fire=false);bind('fire2',()=>fire=true,()=>fire=false);bind('swap',sw);bind('scope',()=>P.sc=!P.sc);bind('drive',drv);bind('prone',()=>{P.prone=!P.prone;if(P.prone)P.crouch=false});bind('rev',rvv);bind('vw',()=>P.tp=!P.tp);bind('lnl',()=>P.lnT=-1,()=>P.lnT=0);bind('lnr',()=>P.lnT=1,()=>P.lnT=0);bind('thr',thr);bind('gsw',gs);bind('jump',jump);bind('crouch',()=>P.crouch=!P.crouch);bind('rel',reload);bind('pjump',jump);bind('pchute',chute);"
# The preceding exact bind block remains the same except the sprint binding was removed.
if anchor not in html: raise SystemExit('control binding block missing')
hold="""\nconst sprintBtn=$('sprint');let sprintPointer=null;\nconst sprintOff=e=>{if(e&&sprintPointer!==null&&e.pointerId!==sprintPointer)return;key.sprint=false;sprintPointer=null;if(sprintBtn)sprintBtn.classList.remove('on')};\nconst sprintOn=e=>{if(!sprintBtn||P.veh||P.air||!started||!P.alive)return;e.preventDefault();e.stopPropagation();sprintPointer=e.pointerId;key.sprint=true;sprintBtn.classList.add('on');try{sprintBtn.setPointerCapture(e.pointerId)}catch(x){}};\nif(sprintBtn){sprintBtn.addEventListener('pointerdown',sprintOn);sprintBtn.addEventListener('pointerup',sprintOff);sprintBtn.addEventListener('pointercancel',sprintOff);sprintBtn.addEventListener('lostpointercapture',sprintOff)}\n"""
html=one(html,anchor,anchor+hold,'hold-to-run pointer lifecycle')
html=one(html,"function clearGameplayInputs(){jid=null;joy={x:0,y:0};kn.style.transform='';lid=null;fire=false;Object.keys(driveInput).forEach(k=>driveInput[k]=0);document.querySelectorAll('.on').forEach(e=>e.classList.remove('on'))}", "function clearGameplayInputs(){jid=null;joy={x:0,y:0};kn.style.transform='';lid=null;fire=false;key.sprint=false;sprintPointer=null;if(sprintBtn)sprintBtn.classList.remove('on');Object.keys(driveInput).forEach(k=>driveInput[k]=0);document.querySelectorAll('.on').forEach(e=>e.classList.remove('on'))}",'global touch interruption reset')
# Add control icons without replacing or detaching existing event listeners.
control="""\nconst bzControlIcons={fire:['✦','FIRE'],fire2:['✦','ALT'],swap:['⇄','SWAP'],scope:['◎','AIM'],drive:['▰','DRIVE'],prone:['⌄','PRONE'],rev:['+','REVIVE'],vw:['◉','VIEW'],lnl:['◁','PEEK'],lnr:['▷','PEEK'],thr:['◌','THROW'],gsw:['◉','GRENADE'],jump:['↑','JUMP'],crouch:['⌄','CROUCH'],rel:['↻','RELOAD'],sprint:['»','RUN'],pjump:['↓','JUMP'],pchute:['◇','CHUTE'],'drive-gas':['▲','GAS'],'drive-brake':['■','BRAKE'],'drive-left':['◀','LEFT'],'drive-right':['▶','RIGHT'],'drive-exit':['↗','EXIT'],'drive-cam':['◉','CAM']};\nObject.entries(bzControlIcons).forEach(([id,v])=>{const e=$(id);if(e)e.innerHTML='<span class=\"bz-control-symbol\">'+v[0]+'</span><small>'+v[1]+'</small>'});\n"""
html=one(html,anchor+hold,anchor+hold+control,'control icon labels')
# Third-person peek now changes the shoulder offset, not merely the roll angle.
html=one(html,"if(P.tp){const bk=3.2,ph=P.pitch;cam.position.set(P.x+sy*bk*Math.cos(ph)+cy*.7,Math.max(.4,P.y+.3-Math.sin(ph)*bk*.8),P.z+cy*bk*Math.cos(ph)-sy*.7)}else cam.position.set(P.x+cy*ln*.6,P.y,P.z-sy*ln*.6);cam.rotation.set(P.pitch,P.yaw,-ln*.25,'YXZ')", "if(P.tp){const bk=3.2,ph=P.pitch,shoulder=.7+ln*.92;cam.position.set(P.x+sy*bk*Math.cos(ph)+cy*shoulder,Math.max(.4,P.y+.3-Math.sin(ph)*bk*.8),P.z+cy*bk*Math.cos(ph)-sy*shoulder)}else cam.position.set(P.x+cy*ln*.6,P.y,P.z-sy*ln*.6);cam.rotation.set(P.pitch,P.yaw,-ln*.34,'YXZ')",'third-person peek camera')
# Context-aware control visibility while moving/running/driving.
html=one(html,"function loop0(n){window.BZGameState={started:!!started,health:Number(P.hp)||0,alive:!!P.alive,weapon:W[P.w]?.n||'Weapon'};const frameMs=Math.max(0,n-last),dt=Math.min(frameMs/1000,.1);last=n;bzAdaptiveQuality(frameMs);", "function loop0(n){window.BZGameState={started:!!started,health:Number(P.hp)||0,alive:!!P.alive,weapon:W[P.w]?.n||'Weapon'};const frameMs=Math.max(0,n-last),dt=Math.min(frameMs/1000,.1);last=n;const bzMove=Math.hypot(joy.x,joy.y)>.12||key.KeyW||key.KeyA||key.KeyS||key.KeyD;document.body.classList.toggle('bz-moving',!!bzMove);document.body.classList.toggle('bz-running',!!(key.sprint||key.ShiftLeft||key.ShiftRight));bzAdaptiveQuality(frameMs);",'movement-aware HUD state')
# World water: bounded vertex ripple and fragment shimmer, no external textures/shaders.
water="""const bzWaterMat=lk.material;bzWaterMat.onBeforeCompile=shader=>{shader.uniforms.bzWaterTime={value:0};shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\\nuniform float bzWaterTime;').replace('#include <begin_vertex>','#include <begin_vertex>\\ntransformed.z += sin(position.x*.34+bzWaterTime*1.25)*.045 + cos(position.y*.29-bzWaterTime*.9)*.035;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\\nuniform float bzWaterTime;').replace('#include <color_fragment>','#include <color_fragment>\\ndiffuseColor.rgb *= .96 + .06*sin(gl_FragCoord.x*.035+gl_FragCoord.y*.021+bzWaterTime*1.8);');bzWaterMat.userData.bzWaterShader=shader};bzWaterMat.customProgramCacheKey=()=> 'bz-water-ripple-v1';bzWaterMat.needsUpdate=true;const bzShore=new THREE.Mesh(new THREE.RingGeometry(lake.r*.96,lake.r*1.025,48),new THREE.MeshBasicMaterial({color:0xa8dff0,transparent:true,opacity:.24,side:THREE.DoubleSide}));bzShore.rotation.x=-Math.PI/2;bzShore.position.set(lake.x,.065,lake.z);S.add(bzShore);"""
html=one(html,"lk.rotation.x=-Math.PI/2;lk.position.set(lake.x,.05,lake.z);S.add(lk);", "lk.rotation.x=-Math.PI/2;lk.position.set(lake.x,.05,lake.z);S.add(lk);"+water,'animated water shader')
html=one(html,"function loop0(n){window.BZGameState={started:!!started,health:Number(P.hp)||0,alive:!!P.alive,weapon:W[P.w]?.n||'Weapon'};", "function loop0(n){const bzWaterShader=lk.material.userData.bzWaterShader;if(bzWaterShader)bzWaterShader.uniforms.bzWaterTime.value=n*.001;window.BZGameState={started:!!started,health:Number(P.hp)||0,alive:!!P.alive,weapon:W[P.w]?.n||'Weapon'};",'animate water time')
# Instanced grass blades: crossed planes, deterministic draw-call budget.
grass="""\n{const count=LQ?460:1320,b1=new THREE.PlaneGeometry(.065,.62),b2=b1.clone();b1.translate(0,.31,0);b2.translate(0,.31,0);b2.rotateY(Math.PI/2);const blades=mergeG([[b1,0,0,0],[b2,0,0,0]]),mat=new THREE.MeshLambertMaterial({color:0xffffff,side:THREE.DoubleSide}),grass=new THREE.InstancedMesh(blades,mat,count),d=new THREE.Object3D(),c=new THREE.Color();let placed=0,tries=0;while(placed<count&&tries<count*4){tries++;const x=rnd(-428,428),z=rnd(-428,428);if(inW(x,z)||Math.hypot(x,z)<12)continue;d.position.set(x,(typeof bzTerrainHeight==='function'?bzTerrainHeight(x,z):0)+.03,z);d.rotation.y=rnd(0,6.28);const sc=rnd(.75,1.55);d.scale.set(sc,rnd(.7,1.35)*sc,sc);d.updateMatrix();grass.setMatrixAt(placed,d.matrix);const h=rnd(.82,1.14);c.setRGB(.34*h,.62*h,.28*h);grass.setColorAt(placed,c);placed++}grass.count=placed;grass.frustumCulled=false;S.add(grass)}\n"""
html=one(html,"inst(new THREE.ConeGeometry(.12,1.1,4),FM(0x5aa63e,1.6,'y',.55,2),LQ?150:420,(o,i)=>pos(o,.55,rnd(.7,1.5)));", "inst(new THREE.ConeGeometry(.12,1.1,4),FM(0x5aa63e,1.6,'y',.55,2),LQ?150:420,(o,i)=>pos(o,.55,rnd(.7,1.5)));"+grass,'instanced ground grass')
