# Root buttresses and lateral branches are merged into the existing instanced trunk meshes.
old="const tkP=new THREE.CylinderGeometry(.2,.38,2.4,7),tkO=new THREE.CylinderGeometry(.26,.45,3.4,7);tkP.translate(0,1.2,0);tkO.translate(0,1.7,0);"
new="const tkP=new THREE.CylinderGeometry(.2,.38,2.4,7),tkO=new THREE.CylinderGeometry(.26,.45,3.4,7);tkP.translate(0,1.2,0);tkO.translate(0,1.7,0);const rootA=new THREE.CylinderGeometry(.035,.17,.78,5),rootB=rootA.clone(),rootC=rootA.clone(),rootD=rootA.clone();rootA.rotation.z=Math.PI/2;rootA.translate(.28,.23,0);rootB.rotation.z=-Math.PI/2;rootB.translate(-.28,.23,0);rootC.rotation.x=Math.PI/2;rootC.translate(0,.23,.28);rootD.rotation.x=-Math.PI/2;rootD.translate(0,.23,-.28);const branchA=new THREE.CylinderGeometry(.045,.1,1.15,5),branchB=branchA.clone(),branchC=branchA.clone();branchA.rotation.z=-.68;branchA.translate(-.34,2.35,.02);branchB.rotation.z=.68;branchB.translate(.34,2.4,-.02);branchC.rotation.x=.68;branchC.translate(.02,2.25,.34);const tkPDetail=mergeG([[tkP,0,0,0],[rootA,0,0,0],[rootB,0,0,0],[rootC,0,0,0],[rootD,0,0,0]]),tkODetail=mergeG([[tkO,0,0,0],[rootA,0,0,0],[rootB,0,0,0],[rootC,0,0,0],[rootD,0,0,0],[branchA,0,0,0],[branchB,0,0,0],[branchC,0,0,0]]);"
html=one(html,old,new,'tree root and branch geometry')
html=one(html,"fill(pines,pineG,tkP,FM(MAP.tc,.18,'y',0,1.1));fill(oaks,oakG,tkO,FM(new THREE.Color(MAP.tc).offsetHSL(.03,.02,.04).getHex(),.2,'y',2,1))", "fill(pines,pineG,tkPDetail,FM(MAP.tc,.18,'y',0,1.1));fill(oaks,oakG,tkODetail,FM(new THREE.Color(MAP.tc).offsetHSL(.03,.02,.04).getHex(),.2,'y',2,1))",'detailed instanced trees')
# Vehicle exterior trim and wheel hubs; wrap the existing builders to retain their behavior.
