veh_wrap="""const bzBaseBuildCar=buildCar;buildCar=function(g){bzBaseBuildCar(g);const u=g.userData,w=u.vw,l=u.vl;if(!u.wheels||u.bike)return;const steel=mS(0x75828b,.38,.72),black=mS(0x161c22,.68,.25);bx(g,w*.58,.18,.08,black,0,.82,l/2+.08);for(let i=0;i<5;i++)bx(g,.035,.13,.045,steel,(i-2)*w*.11,.83,l/2+.13);[-1,1].forEach(side=>{bx(g,.09,.13,.16,black,side*w*.5,1.22,l*.12);bx(g,.07,.09,.12,steel,side*w*.51,1.24,l*.12)});if(l<8){[-1,1].forEach(side=>{bx(g,.045,.06,l*.58,steel,side*w*.39,1.82,-.02)});bx(g,w*.76,.06,.1,steel,0,1.96,0)}u.wheels.forEach(wh=>{cyl(wh,.085,.085,.045,steel,0,0,0,0,0,Math.PI/2,10)})};\n"""
